/**
 * Role changes and the last-owner invariant.
 *
 * Owner C implements `@/server/services/member-service`.
 */
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import * as memberRepo from "@/server/repositories/member-repository";
import * as memberService from "@/server/services/member-service";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterAll(() => {
  cleanup();
});

describe("services/member-service", () => {
  // can(actor, "member:update_role", …) gates the change; a member cannot self-promote.
  it("refuses a role change to an actor without member:update_role", async () => {
    const tenant = await createTenant("member-role-forbidden", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.member, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "admin",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
  });

  // The org must always retain at least one owner.
  it("refuses to demote the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-demote", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
        role: "admin",
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // Demoting an owner is fine while another owner exists.
  it("allows demoting an owner when another owner remains", async () => {
    const tenant = await createTenant("member-second-owner", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    const adminMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!ownerMember || !adminMember) throw new Error("fixture member missing");

    // Promote the admin to owner first, so two owners exist.
    await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: adminMember.id,
      role: "owner",
    });

    const demoted = await memberService.updateMemberRole(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: ownerMember.id,
      role: "admin",
    });

    expect(demoted.role).toBe("admin");
  });

  // member.role_changed carries both the previous and the new role.
  it("emits member.role_changed with from and to", async () => {
    const tenant = await createTenant("member-role-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.role_changed", (payload) => resolve(payload));
      void memberService.updateMemberRole(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
        role: "member",
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      from: "admin",
      to: "member",
    });
  });

  // Removing the last owner is refused for the same invariant.
  it("refuses to remove the last remaining owner", async () => {
    const tenant = await createTenant("member-last-owner-remove", "growth");
    const ownerMember = await memberRepo.findMember(tenant.org.id, tenant.userIds.owner);
    if (!ownerMember) throw new Error("fixture owner missing");

    await expect(
      memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: ownerMember.id,
      }),
    ).rejects.toThrow(/at least one owner/);
  });

  // member.removed carries the memberId and userId that left.
  it("emits member.removed when a member is removed", async () => {
    const tenant = await createTenant("member-remove-emit", "growth");
    const target = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!target) throw new Error("fixture member missing");

    let off: Unsubscribe | undefined;
    const received = await new Promise((resolve) => {
      off = subscribe("member.removed", (payload) => resolve(payload));
      void memberService.removeMember(tenant.actors.owner, {
        orgId: tenant.org.id,
        memberId: target.id,
      });
    });
    off?.();

    expect(received).toMatchObject({
      orgId: tenant.org.id,
      memberId: target.id,
      userId: tenant.userIds.viewer,
    });
  });
});
/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
/**
 * Fixtures for the server suite: a throwaway SQLite file plus a helper that
 * builds one fully-populated tenant (org, four members, a project) through the
 * real repositories, so the rows under test are the rows production writes.
 *
 * Kept apart from `tests/helpers/*` — those belong to another owner.
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "@/server/db/migrate";
import * as memberRepo from "@/server/repositories/member-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as userRepo from "@/server/repositories/user-repository";
import type { PlanId } from "@/types/billing";
import type { OrgId, UserId } from "@/types/common";
import type { Actor, Role } from "@/types/member";
import type { Organization } from "@/types/organization";
import type { Project } from "@/types/project";

export interface Tenant {
  readonly org: Organization;
  readonly project: Project;
  readonly actors: Readonly<Record<Role, Actor>>;
  readonly userIds: Readonly<Record<Role, UserId>>;
}

const ROLES: readonly Role[] = ["owner", "admin", "member", "viewer"];

/**
 * Points the connection at a fresh database file and migrates it. Call from
 * `beforeAll`; the returned function removes the directory again.
 *
 * A file rather than `:memory:` because `runMigrations` and the app client
 * open separate connections, and only a file is shared between the two.
 */
export async function useTemporaryDatabase(): Promise<() => void> {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-test-"));
  const path = join(dir, "taskflow.db");

  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);

  return () => {
    rmSync(dir, { recursive: true, force: true });
  };
}

/**
 * Creates one organization with a member in every role and a single project.
 * `plan` decides which quotas apply — the free plan's three seats is what the
 * invite-limit test leans on.
 */
export async function createTenant(
  slug: string,
  plan: PlanId = "growth",
): Promise<Tenant> {
  const owner = await userRepo.insertUser({
    email: `owner@${slug}.test`,
    name: `${slug} owner`,
    passwordHash: "seed",
  });

  const org = await orgRepo.insertOrg(
    { name: `${slug} inc`, slug, plan },
    owner.id,
  );

  await subscriptionRepo.insertSubscription(org.id, plan, "monthly");

  const userIds: Partial<Record<Role, UserId>> = {};
  const actors: Partial<Record<Role, Actor>> = {};

  for (const role of ROLES) {
    const user =
      role === "owner"
        ? owner
        : await userRepo.insertUser({
            email: `${role}@${slug}.test`,
            name: `${slug} ${role}`,
            passwordHash: "seed",
          });

    await memberRepo.insertMember(org.id, user.id, role, null);

    userIds[role] = user.id;
    actors[role] = { userId: user.id, orgId: org.id, role };
  }

  const project = await projectRepo.insertProject({
    orgId: org.id,
    name: `${slug} platform`,
    slug: "platform",
    key: "PLAT",
    description: null,
