/**
 * Ownership handover offers. At most one row per org is `pending` at a time;
 * whether a pending row has lapsed is decided by the caller against `expiresAt`.
 */
import { and, desc, eq, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: IsoTimestamp,
  expiresAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt,
      updatedAt: createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** Every row still marked `pending`, lapsed or not, newest first. */
export async function listPendingHandovers(
  orgId: OrgId,
): Promise<readonly OwnershipHandover[]> {
  const rows = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt), desc(ownershipHandovers.id))
    .all();

  return rows.map(toOwnershipHandover);
}

/** Moves a pending row to its final status. */
export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending">,
  resolvedAt: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt, updatedAt: toIsoTimestamp(new Date()) })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${handoverId} not found`);
  return toOwnershipHandover(row);
}

/** Withdraws every pending offer the user is party to, on either side. */
export async function cancelPendingHandoversForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<number> {
  const result = getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();

  return result.changes;
}
