 * do this — holding the owner role is not enough — and only one offer may be
 * open per workspace.
 */
export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await requireRecordedOwner(actor, orgId);

  if (toUserId === org.ownerId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  if ((await findOpenHandover(org, now)) !== null) {
    throw new OwnershipHandoverError("pending_exists");
  }

  // Lapsed offers are still marked pending; close them before opening another.
  for (const stale of await handoverRepo.listPendingHandovers(orgId)) {
    await handoverRepo.resolveHandover(orgId, stale.id, "expired", stale.expiresAt);
  }

  const handover = await handoverRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    toIsoTimestamp(now),
    toIsoTimestamp(new Date(now.getTime() + HANDOVER_TTL_MS)),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You were offered ownership of a workspace",
    body: `${org.name} can be yours: accept to become its owner`,
    href: "/settings/danger",
    actorId: actor.userId,
  });

  return handover;
}

/**
 * The offered member takes the workspace over. The new owner is promoted
 * before the previous one steps down, so the org never lacks an owner.
 */
export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const handover = await requireActionableHandover(actor, orgId);
  const stamp = toIsoTimestamp(new Date());

  // Resolve first so the same offer cannot be accepted twice.
  await handoverRepo.resolveHandover(orgId, handover.id, "accepted", stamp);

  const incoming = requireFound(
    await memberRepo.findMember(orgId, actor.userId),
    "Member",
    actor.userId,
  );

  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(
      orgId,
      incoming.id,
      "owner",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  await orgRepo.updateOrgOwner(orgId, actor.userId);

  const outgoing = await memberRepo.findMember(orgId, handover.fromUserId);
  if (outgoing && outgoing.role === "owner") {
    await assertLastOwnerRetained(orgId, outgoing.id, "admin");
    const demoted = await memberRepo.updateMemberRole(
      orgId,
      outgoing.id,
      "admin",
    );
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: demoted.id,
      from: outgoing.role,
      to: demoted.role,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: handover.fromUserId,
    toUserId: actor.userId,
  });

  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const handover = await requireActionableHandover(actor, orgId);
  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

/** The recorded owner withdraws their open offer. */
export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await requireRecordedOwner(actor, orgId);

  const now = new Date();
  const handover = await findOpenHandover(org, now);
  if (handover === null) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    handover.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

/** The open offer, if any; visible to every member of the workspace. */
export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));

  const org = requireFound(
