/**
 * Handovers belong to the recorded owner, not to whoever holds the owner
 * role, so the role matrix alone cannot decide this.
 */
async function requireRecordedOwner(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );

  if (org.ownerId !== actor.userId) {
