/**
 * The newest pending offer whose parties are still in place, lapsed or not.
 * An offer whose sender is no longer the recorded owner, or whose either side
 * has left the workspace, is withdrawn on the way past.
 */
async function findLiveHandover(
  org: Organization,
): Promise<OwnershipHandover | null> {
  for (const handover of await handoverRepo.listPendingHandovers(org.id)) {
    if (await partiesInPlace(org, handover)) return handover;

    await handoverRepo.resolveHandover(
