    "Organization",
    orgId,
  );

  const handover = await findLiveHandover(org);
  if (handover === null || handover.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (hasLapsed(handover, new Date())) {
    throw new OwnershipHandoverError("expired");
  }
  return handover;
}

/** An offer made at T may be acted on before T + 7 days, never from then on. */
function hasLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= Date.parse(handover.expiresAt);
}

async function partiesInPlace(
  org: Organization,
  handover: OwnershipHandover,
): Promise<boolean> {
  if (handover.fromUserId !== org.ownerId) return false;

  for (const userId of [handover.fromUserId, handover.toUserId]) {
    const member = await memberRepo.findMember(org.id, userId);
    if (!member || member.status !== "active") return false;
  }
  return true;
}
