cat > tests/services/zz-tmp-handover.test.ts <<'EOF'
import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);
import { subscribe, emit } from "@/lib/event-bus";
import { OwnershipHandoverError, toAppError } from "@/lib/errors";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as memberRepo from "@/server/repositories/member-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as org from "@/server/services/organization-service";
import * as memberService from "@/server/services/member-service";
import * as billing from "@/server/services/billing-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { listNotifications } from "@/server/services/notification-service";
import { NotFoundError } from "@/server/services/_support";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerActivityListeners(); });
afterAll(() => cleanup());

describe("handover", () => {
  it("full flow", async () => {
    const t = await createTenant("ho1");
    const other = await createTenant("ho2");
    const events: unknown[] = [];
    subscribe("member.role_changed", (p) => { events.push(p); });
    subscribe("organization.ownership_transferred", (p) => { events.push(p); });

    await expect(org.initiateOwnershipHandover(t.actors.admin, t.org.id, t.userIds.member)).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, other.org.id, t.userIds.member)).rejects.toBeInstanceOf(TenantScopeError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, other.userIds.member)).rejects.toBeInstanceOf(NotFoundError);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.owner)).rejects.toMatchObject({ reason: "self" });
    const h = await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.member);
    expect(Date.parse(h.expiresAt) - Date.parse(h.createdAt)).toBe(7 * 86400000);
    await expect(org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.admin)).rejects.toMatchObject({ reason: "pending_exists" });
    expect((await org.getPendingOwnershipHandover(t.actors.viewer, t.org.id))?.toUserId).toBe(t.userIds.member);
    const notes = await listNotifications(t.actors.member, { orgId: t.org.id, recipientId: t.userIds.member, unreadOnly: false, limit: 20, cursor: null });
    expect(notes.items.map((n) => n.kind)).toContain("ownership_handover");
    await expect(org.acceptOwnershipHandover(t.actors.admin, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    const updated = await org.acceptOwnershipHandover(t.actors.member, t.org.id);
    expect(updated.ownerId).toBe(t.userIds.member);
    expect((await memberRepo.findMember(t.org.id, t.userIds.owner))?.role).toBe("admin");
    expect((await memberRepo.findMember(t.org.id, t.userIds.member))?.role).toBe("owner");
    expect(events).toHaveLength(3);
    console.log(events);
    await expect(org.acceptOwnershipHandover(t.actors.member, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    await expect(billing.changePlan(t.actors.owner, { orgId: t.org.id, plan: "enterprise", interval: "monthly" } as never)).rejects.toBeInstanceOf(PermissionDeniedError);
    await billing.changePlan(t.actors.member, { orgId: t.org.id, plan: "enterprise", interval: "monthly" } as never);
    const act = await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never);
    console.log(act.items.filter((a) => a.action === "organization.ownership_transferred"));
    const newOwner = { ...t.actors.member, role: "owner" as const };
    const prev = await memberRepo.findMember(t.org.id, t.userIds.owner);
    await memberService.removeMember(newOwner, { orgId: t.org.id, memberId: prev!.id });
    expect(toAppError(new OwnershipHandoverError("expired")).code).toBe("conflict");
    void emit;
  });

  it("expiry and removal", async () => {
    const t = await createTenant("ho3");
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));
    await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    vi.setSystemTime(new Date("2026-01-07T23:59:59.999Z"));
    expect(await org.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).not.toBeNull();
    vi.setSystemTime(new Date("2026-01-08T00:00:00.000Z"));
    expect(await org.getPendingOwnershipHandover(t.actors.viewer, t.org.id)).toBeNull();
    await expect(org.acceptOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(org.declineOwnershipHandover(t.actors.viewer, t.org.id)).rejects.toMatchObject({ reason: "expired" });
    await expect(org.cancelOwnershipHandover(t.actors.owner, t.org.id)).rejects.toMatchObject({ reason: "nothing_pending" });
    const h2 = await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    const d = await org.declineOwnershipHandover(t.actors.viewer, t.org.id);
    expect(d.status).toBe("declined");
    await org.initiateOwnershipHandover(t.actors.owner, t.org.id, t.userIds.viewer);
    const vm = await memberRepo.findMember(t.org.id, t.userIds.viewer);
    await memberService.removeMember(t.actors.owner, { orgId: t.org.id, memberId: vm!.id });
    expect(await org.getPendingOwnershipHandover(t.actors.admin, t.org.id)).toBeNull();
    vi.useRealTimers();
    void h2;
  });
});
EOF
